/* 精简代码高亮（无需外部依赖）
 * 支持：Python, JavaScript, Bash, JSON, YAML, 通用
 */
(function(global) {
  'use strict';

  function escapeHtml(text) {
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
  }

  function highlight(text, lang) {
    if (!text) return '';
    text = escapeHtml(text);

    const langLower = (lang || '').toLowerCase();

    // Python
    if (langLower.includes('py') || langLower.includes('python')) {
      text = text.replace(/\b(def|class|return|if|elif|else|for|while|import|from|as|with|try|except|finally|raise|yield|lambda|pass|break|continue|not|and|or|in|is|None|True|False|self)\b/g, '<span style="color:#ff7b72">$1</span>');
      text = text.replace(/(#[^\n]*)/g, '<span style="color:#8b949e">$1</span>');
      text = text.replace(/("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')/g, '<span style="color:#a5d6ff">$1</span>');
      text = text.replace(/\b(\d+\.?\d*)\b/g, '<span style="color:#79c0ff">$1</span>');
    }
    // JavaScript
    else if (langLower.includes('js') || langLower.includes('javascript') || langLower.includes('ts')) {
      text = text.replace(/\b(function|const|let|var|if|else|for|while|return|import|export|from|async|await|new|class|this|null|undefined|true|false)\b/g, '<span style="color:#ff7b72">$1</span>');
      text = text.replace(/(\/\/[^\n]*)/g, '<span style="color:#8b949e">$1</span>');
      text = text.replace(/("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|`(?:[^`\\]|\\.)*`)/g, '<span style="color:#a5d6ff">$1</span>');
      text = text.replace(/\b(\d+\.?\d*)\b/g, '<span style="color:#79c0ff">$1</span>');
    }
    // Bash / Shell
    else if (langLower.includes('sh') || langLower.includes('bash') || langLower.includes('shell')) {
      text = text.replace(/(#[^\n]*)/g, '<span style="color:#8b949e">$1</span>');
      text = text.replace(/("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')/g, '<span style="color:#a5d6ff">$1</span>');
      text = text.replace(/\b(if|then|else|fi|for|do|done|while|case|esac|function|echo|cd|ls|rm|mkdir|cp|mv|cat|grep|find|xargs|awk|sed|sort|head|tail|which|export|source)\b/g, '<span style="color:#ff7b72">$1</span>');
    }
    // JSON
    else if (langLower.includes('json')) {
      text = text.replace(/("(?:[^"\\]|\\.)*")(\s*:)/g, '<span style="color:#79c0ff">$1</span>$2');
      text = text.replace(/:\s*("(?:[^"\\]|\\.)*")/g, ': <span style="color:#a5d6ff">$1</span>');
      text = text.replace(/\b(true|false|null)\b/g, '<span style="color:#ff7b72">$1</span>');
      text = text.replace(/\b(-?\d+\.?\d*)\b/g, '<span style="color:#79c0ff">$1</span>');
    }
    // YAML
    else if (langLower.includes('yaml') || langLower.includes('yml')) {
      text = text.replace(/(#[^\n]*)/g, '<span style="color:#8b949e">$1</span>');
      text = text.replace(/^(\s*)([\w\-]+)(\s*:)/gm, '$1<span style="color:#79c0ff">$2</span>$3');
      text = text.replace(/("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')/g, '<span style="color:#a5d6ff">$1</span>');
    }
    // SQL
    else if (langLower.includes('sql')) {
      text = text.replace(/\b(SELECT|FROM|WHERE|INSERT|UPDATE|DELETE|CREATE|DROP|ALTER|TABLE|INTO|VALUES|SET|JOIN|ON|AND|OR|NOT|NULL|AS|ORDER|BY|GROUP|HAVING|LIMIT|OFFSET|COUNT|SUM|AVG|MIN|MAX|DISTINCT|IN|BETWEEN|LIKE|EXISTS|CASE|WHEN|THEN|ELSE|END)\b/gi, '<span style="color:#ff7b72">$1</span>');
      text = text.replace(/(--[^\n]*)/g, '<span style="color:#8b949e">$1</span>');
      text = text.replace(/("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')/g, '<span style="color:#a5d6ff">$1</span>');
    }
    // 通用 fallback
    else {
      text = text.replace(/(#[^\n]*|\/\/[^\n]*)/g, '<span style="color:#8b949e">$1</span>');
      text = text.replace(/("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')/g, '<span style="color:#a5d6ff">$1</span>');
      text = text.replace(/\b(\d+\.?\d*)\b/g, '<span style="color:#79c0ff">$1</span>');
    }

    return text;
  }

  global.hljs = {
    highlight: function(text, lang) {
      return highlight(text, lang);
    },
    highlightAll: function() {
      document.querySelectorAll('pre code').forEach(function(block) {
        var parent = block.parentElement;
        var lang = '';
        if (parent.classList) {
          for (var i = 0; i < parent.classList.length; i++) {
            if (parent.classList[i].startsWith('language-')) {
              lang = parent.classList[i].slice(9);
              break;
            }
          }
        }
        var text = block.textContent;
        block.innerHTML = highlight(text, lang);
      });
    }
  };
})(window);
